package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.rollup.Figures;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.RequestBody;

public class TransferPerson {
    // Only a steward (a delegation included) transfers a person who is not retired, to another sheet that is not archived
    // and has none of their name, aliases or contact, unless one person there has their name or an alias of theirs:
    // they are then merged into that person (who must not be retired), as a merge does. Each numbered claim takes the next number of the other sheet, in
    // the order the claims were opened (the sheet's today when each was first opened, then the order they were added).
    public void transfer(@RequestBody(required = false) TransferRequest body, @Val Person person, People people,
            Claims claims, Settings settings, Sheets sheets, Periods periods, Rollup rollup,
            ServerHttpConnection connection, Out<TransferredPerson> transferredOut, Out<PersonResponse> responseOut)
            throws PersonTransferRefusedException {
        if (!Settings.STEWARD.equals(settings.role(person.sheetId(), Audit.user(connection).trim()))) {
            throw new PersonTransferRefusedException("Only a steward can transfer a person.");
        }
        String to = body == null || body.toSheetId() == null ? "" : body.toSheetId().trim();
        if (to.isEmpty()) {
            throw new PersonTransferRefusedException("Give the id of the sheet to transfer to.");
        }
        if (to.equals(person.sheetId())) {
            throw new PersonTransferRefusedException("A person cannot be transferred to their own sheet.");
        }
        if (person.retired()) {
            throw new PersonTransferRefusedException("A retired person cannot be transferred.");
        }
        if (sheets.isArchived(to)) {
            throw new PersonTransferRefusedException("The sheet " + to + " is archived.");
        }
        // A person on the other sheet with their name or an alias of theirs is merged into, as a merge does.
        List<String> names = new ArrayList<>();
        names.add(person.name());
        names.addAll(person.aliases());
        Person into = names.stream().map(n -> people.findByName(to, n)).filter(Objects::nonNull).findFirst().orElse(null);
        for (String name : names) {
            Person holder = people.findByName(to, name);
            if (holder == null ? people.nameTaken(to, name, person.id()) : holder.id() != into.id()) {
                throw new PersonTransferRefusedException("A name or alias of theirs is already on the sheet " + to + ".");
            }
        }
        if (into != null && into.retired()) {
            throw new PersonTransferRefusedException("A retired person cannot be merged.");
        }
        if (into == null && person.contact() != null && people.contactTaken(to, person.contact(), -1)) {
            throw new PersonTransferRefusedException("Their contact is already on the sheet " + to + ".");
        }
        Figures before = rollup.figures(to);

        // The numbered claims in the order they were opened, each given the next number of the other sheet.
        Map<Long, LocalDate> opened = claims.openedOn(person.sheetId());
        List<Claim> numbered = new ArrayList<>(claims.list(person.sheetId()).stream()
                .filter(c -> c.personId() == person.id() && c.number() != null).toList());
        numbered.sort(Comparator.<Claim, LocalDate>comparing(c -> opened.getOrDefault(c.id(), c.date()))
                .thenComparingLong(Claim::id));
        LocalDate numberingFrom = settings.periodNumberingFrom(to);
        boolean byPeriod = numberingFrom != null && !sheets.today(to).isBefore(numberingFrom);
        Map<Long, String> numbers = new LinkedHashMap<>();
        for (Claim claim : numbered) {
            String scope = null;
            if (byPeriod) {
                Period period = periods.on(to, claim.dueBy());
                scope = period == null ? "" : period.name();
            }
            numbers.put(claim.id(), claims.number(to, scope, claim.dueBy() == null ? claim.date() : claim.dueBy()));
        }

        long arrived = people.transfer(person, to, numbers, into == null ? null : into.id());
        sheets.markLoaded(to);
        transferredOut.set(new TransferredPerson(person, to, before, into));
        responseOut.set(PersonResponse.from(people.find(to, arrived), sheets.today(to)));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Figures;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupLines;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditPersonTransferred {
    // Each sheet records the transfer (the other sheet then the merge, when they were merged into someone there), then the ROLLUP and TOTALS lines for what moved on it.
    public void audit(@Val TransferredPerson transferred, @Val Figures before, Rollup rollup,
            ServerHttpConnection connection, Audit audit) {
        String user = Audit.user(connection);
        String from = transferred.from().sheetId();
        String to = transferred.toSheetId();
        String name = transferred.from().name();
        audit.record(Audit.line("PERSON_TRANSFERRED", from, user, "name=" + name, "to=" + to));
        RollupLines.record(from, user, before, rollup, audit);
        audit.record(Audit.line("PERSON_TRANSFERRED", to, user, "name=" + name, "from=" + from));
        if (transferred.into() != null) {
            audit.record(Audit.line("PERSON_MERGED", to, user, "from=" + name, "into=" + transferred.into().name()));
        }
        RollupLines.record(to, user, transferred.toBefore(), rollup, audit);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Figures;

/**
 * A transfer done: the person transferred ({@code from}, now gone from their sheet), the sheet they went to, and that
 * sheet's figures before they arrived (for its ROLLUP and TOTALS lines), and the person there they were merged into
 * ({@code null} when they arrived as themselves).
 */
public record TransferredPerson(Person from, String toSheetId, Figures toBefore, Person into) {
}
package net.officefloor.hq.app.person;

/** The body of a transfer: the id of the sheet the person goes to. */
public record TransferRequest(String toSheetId) {
}
